propre poao qrunsch abro.warp:
shader_body
{
    float3 rc = lerp(float3(0,0,0), float3(0,1,0), uv.y);
    uv = float2(uv.x, uv.y+0.005*rc.y);


    float3 boxave = (GetPixel(float2(uv.x+texsize.z*q2,uv.y+texsize.w*q2)) +
                     GetPixel(float2(uv.x-texsize.z*q2,uv.y+texsize.w*q2)) +
                     GetPixel(float2(uv.x-texsize.z*q2,uv.y-texsize.w*q2)) +
                     GetPixel(float2(uv.x+texsize.z*q2,uv.y-texsize.w*q2)) ) / 4;
    ret = tex2D(sampler_main, uv);
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q27
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q29
                     );
if(ret.x> q21*q13         && ret.x<= q24*q11        )ret.y += (noise9).x*.5; 
if(ret.y> q22*q11         && ret.y<= q25*q12        )ret.z += (noise9).y*.5; 
if(ret.z> q23*q12         && ret.z<= q26*q13        )ret.x += (noise9).z*.5; 
//    ret = cross(boxave, 1-ret)*1.2;

    //ret -= 0.002;
    //ret *= 0.995;
ret.z=1-ret.y;
ret.y=1-ret.x;
ret.x=1-ret.z;
}

propre poao qrunsch abro.comp:
shader_body
{
    uv = 0.05 + 0.9*uv;

    // equivalent of a laplacian: [center*4 - each of the 4 neighbors*1]
    ret = 0;
    ret += tex2D(sampler_main, uv ).xyz*4;
    ret -= GetBlur1(uv)*3;

    // little bit of noise:
    ret *= 1 + 0.12*(tex2D(sampler_noise_lq, rand_frame.xy 
           + uv*texsize.xy*texsize_noise_lq.zw).xxx*2-1);

    // palettize:
    ret = pow(ret, float3(0.5, 0.5, 0.7));

    ret = (ret-0.1)*1.1;

    //ret.xyz *= 2; // a little bit of overbright
}

