shader_body
{
float2 d = texsize.zw*3;
float3 dx = GetBlur1(uv + float2(1,0)*d) - GetBlur1(uv + float2(-1,0)*d);
float3 dy = GetBlur1(uv + float2(0,1)*d) - GetBlur1(uv + float2(0,-1)*d);
float2 uv1 = frac(uv - float2(dx.y,dy.y)*1 - float2(dx.z,dy.z)*rad*2);
float2 uv_swimmer =frac(0.5 + (uv-0.5)+float2(q19,q20)*float2(-1,1));
dx = GetBlur1(uv_swimmer + float2(1,0)*d) - GetBlur1(uv_swimmer + float2(-1,0)*d);
dy = GetBlur1(uv_swimmer + float2(0,1)*d) - GetBlur1(uv_swimmer + float2(0,-1)*d);
uv1 -= float2(dx.x,dy.x)*4;

ret = lerp(ret,1,GetBlur2(uv1).y);
ret-=roam_sin.zyx*roam_cos.ywx;
ret = lerp(ret,float3(1,0.5,0),GetPixel(uv).y);
ret = lerp(ret,float3(1,1,1),GetPixel(uv-float2(dx.x,dy.x)*0.2).z*saturate(1-rad*1.5));



ret = lerp(ret, 1, GetBlur1(uv_swimmer+float2(dx.x,dy.x)*0.3).x);
ret = lerp(ret,float3(0.5,0,1),GetPixel(uv_swimmer).x);
float4 noise2 = tex3D(sampler_noisevol_hq, 
                      ((uv1.xyy
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*0.4 
                     );
ret -= (noise2)*.2; 
}

