shifter - parchment (MGMT) roe v wade =.warp:
shader_body
{
float2 pixelsize = texsize.zw;

float zm = .98;
float2 cen = float2(q4,q5);

float2 uvm = uv_orig;
uvm = (uvm-cen)*zm+cen;

float2 noise_uv = uv_orig*texsize.xy*texsize_noise_hq.zw + rand_frame.xy;
float4 noiseVal = tex2D(sampler_noise_hq, noise_uv*8);

ret.xyz = saturate(tex2D( sampler_pw_main,uvm).xyz*float3(1,1,.97) - float3(.0,.0,.001));
float3 ret7=ret;
if(frame%3==0)ret.z=.71-ret7.x;



float3 rsamp = tex2D(sampler_pw_main,uvm + (noiseVal.xy-.5)*6*pixelsize).xyz;

ret.xy = (ret.xy-cen)/zm+cen;
rsamp.xy = (rsamp.xy-cen)/zm+cen;

if (length(ret.xy - uv_orig) > length(rsamp.xy - uv_orig)) {
ret.xy = rsamp.xy;
ret.z = rsamp.z;
}

if(frame%5==0)ret.x=.71-ret7.y;
if(frame%7==0)ret.y=.71-ret7.z;


ret.xy *= pow(ret.z,.01);


}

