shader_body
{

//As a base, sample the main sampler at normal uv coordinates and store as return value:
ret = tex2D(sampler_main, uv).xyz;

//Define the translation in (x,y)-direction and multiply by texsize.zw to convert the length to pixels:
float2 shift = float2(0,0)*texsize.zw; 

//Take the original uv coordinates as a starting point, store in second set of coordinates:
float2 uv2 = uv;

//Start iterations...
int n = 1;
while (n<=10) {

//First step: put origin in center;
uv2 = uv2-.5;

//Next, rotate by a factor we set in the per-frame equations - q32 is cos(angle) and q31 is sin(angle): 
uv2 = float2((uv2.x)*q32 - (uv2.y) * q31,(uv2.x)* q31 + (uv2.y) * q32)+.5;

//Then, shift uv coordinates n times - see the step after the next as to why:
uv2 += n*shift;

//Sample the main sampler at our new uv2 coordinates, 
//deduct the result from the current return value, 
//store in ret as absolute (difference) value:
ret = abs(ret-GetPixel(uv2));

//Remove the shift so we won't rotate it with our coordinates in the next iteration:
uv2 -= n*shift;

//Iteration +1
n++;
}

}

