{
    // sample previous frame, with some trails...
    float trail_decay = 0.95;
    ret = tex2D( sampler_fc_main, uv ).xyz;
float3 ret7=ret;
if(frame%3==0)ret.z=.71-ret7.x;

    float3 s2 = tex2D( sampler_fc_main, lerp(uv,uv_orig,0.33) ).xyz*trail_decay;
    ret = max(ret, s2);

if(frame%5==0)ret.x=.71-ret7.y;

float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q27
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q29
                     );
if(ret.x> q21*q13         && ret.x<= q24*q11        )ret.y -= (noise9).x*.5; 
if(ret.y> q22*q11         && ret.y<= q25*q12        )ret.z -= (noise9).y*.5; 
if(ret.z> q23*q12         && ret.z<= q26*q13        )ret.x -= (noise9).z*.5; 
    // a color-holding posterize effect:  
    float3 m = float3(7,6,8);
    ret = lerp(ret, floor(ret*m+0.25)/m, 0.1);


    // darken over time
    float center = 1-saturate(length(uv-uv_orig)*40);
    ret = (ret*0.995 - 0.001 - center*0.002); 

if(frame%7==0)ret.y=.71-ret7.z;


}

