if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5; 
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5; 
    ret+=length(float2(lx,ly));

    ret=lerp(lum(ret),ret,sat*32); //over-saturate
    ret=lerp(ret,tex2D(sampler_fw_cells,ret.xy*.4+.6),.15); //take stripes from image
    ret *= 1.80; //gamma
}

