Phat_Zylot_EoS Come_fly_with_me_vidio_ec.warp:
shader_body
{
    float2 d = texsize.zw*12;
    float2 uv_y = uv_orig;
    float3 dx = ( 2*GetBlur1(uv_y + float2(1,0)*d) - 2*GetBlur1(uv_y-float2(1,0)*d) )*0.5;
    float3 dy = ( 2*GetBlur1(uv_y + float2(0,1)*d) - 2*GetBlur1(uv_y-float2(0,1)*d) )*0.5;
    uv_y = uv_y - float2(dx.y,dy.y)*texsize.zw;

    float2 dither_uv = uv_orig*texsize.xy*texsize_noise_lq.zw*0.8 + rand_frame.xy;
    float2 uv_bg = uv_orig + float2(dx.x,dy.x)*texsize.zw*2 + (tex2D(sampler_noise_lq, dither_uv).xy-0.5)*texsize.zw*4;

ret.x = GetPixel(uv_bg).x - (GetPixel(uv_bg).x - GetBlur3(uv_bg).x)*0.02 - 0.008 + 
(tex2D(sampler_noise_lq, dither_uv).x-0.5)*0.1;
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv_y.xyy*q27
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q29
                     );
if(ret.x> q21*q13         && ret.x<= q24*q11        )ret.y += (noise9).x*.5; 
if(ret.y> q22*q11         && ret.y<= q25*q12        )ret.z += (noise9).y*.5; 
if(ret.z> q23*q12         && ret.z<= q26*q13        )ret.x += (noise9).z*.5; 
ret.y = max(tex2d(sampler_fc_main, uv_orig + texsize.zw*float2(3,0)-float2(dx.y,dy.y)*texsize.zw*2).y,ret.x) - 0.004;


ret.z = max(tex2d(sampler_fc_main, 0.5 + (uv_orig-0.5)*1.4 - float2(0.2,0) - float2(dx.z,dy.z)*texsize.zw*8).z,ret.y) - 0.02;


}

Phat_Zylot_EoS Come_fly_with_me_vidio_ec.comp:
shader_body
{
    float2 d = texsize.zw;
    float3 dx = ( GetPixel(uv+float2(1,0)*d)-GetPixel(uv-float2(1,0)*d) );
    float3 dy = ( GetPixel(uv+float2(0,1)*d)-GetPixel(uv-float2(0,1)*d) );
float2 dz = float2(dx.y,dy.y)*3;

d = texsize.zw*2;
dx = ( GetBlur1(uv+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) );
dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );

dz +=float2(dx.y,dy.y);

float3 bg = pow(length(dz)*0.8+0,0.7)*2 + GetBlur1(uv).y*2;

ret = bg*float3(0.2,0.3,0.6);
float2 uv_swimmer =frac(0.5 + (uv-0.5)+float2(q19,q20)*float2(-1,1));
ret = lerp(ret,float3(3,2,1),GetBlur3(uv_swimmer -float2(dx.y,dy.y)).x);
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q28
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q31
                     );
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5; 
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5; 
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5; 
ret = lerp(ret,0,GetBlur2(uv_swimmer-dz).x);
ret = lerp(ret,float3(0,0,0),1.5*GetPixel(uv_swimmer).x);

//ret = GetPixel(uv);
}

