shader_body
{
    // sample previous frame
    float2 muv;
    muv.x = uv.x-((.01*cos(uv.x*(5+2*bass_att)+time))+(.01*cos(uv.y*(5+2*bass_att)+time)))*.5*treb_att; 
    muv.y = uv.y+((.01*sin(uv.x*(5+2*mid_att)+time))-(.01*cos(uv.y*(5+2*mid_att)+time)))*.5*bass_att;
    float3 blur1 = GetBlur2(muv);
    ret = tex2D( sampler_pw_main, muv ).xyz;
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q27
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q29
                     );
if(ret.x> q21*q13         && ret.x<= q24*q11        )ret.y += (noise9).x*.5; 
if(ret.y> q22*q11         && ret.y<= q25*q12        )ret.z += (noise9).y*.5; 
if(ret.z> q23*q12         && ret.z<= q26*q13        )ret.x += (noise9).z*.5; 
    ret.x = ret.x+(blur1.x)*(bass_att*.05);
    ret.y = ret.y+(blur1.y)*(treb_att*.05);
    ret.z = ret.z+(blur1.z)*(mid_att*.05); 
    if(ret.x > .9){
      ret.x = 0;
    }
    if(ret.y > .9){
      ret.y = 0;
    }
    if(ret.z > .9){
      ret.z = 0;
    }
}

