shader_body
{
    uv = 0.05 + 0.9*uv;

    // equivalent of a laplacian: [center*4 - each of the 4 neighbors*1]
    ret = 0;
    ret += tex2D(sampler_main, uv ).xyz;
    ret += .25*GetBlur1(uv);

    float2 uv_echo; 
    uv_echo.x = (uv.y - 0.5)*(-1) + 0.5;
    uv_echo.y = uv.x;

    float3 ret2;
    ret2 = tex2D(sampler_main, uv_echo ).xyz;
    ret2 += .25*GetBlur1(uv_echo);

    float2 uv_echo2; 
    uv_echo2.y = (uv.x - 0.5)*(-1) + 0.5;
    uv_echo2.x = uv.y;

    float3 ret3;
    ret3 = tex2D(sampler_main, uv_echo2 ).xyz;
    ret3 += .25* GetBlur1(uv_echo2);

    float2 uv_echo3; 
    uv_echo3 = (uv - 0.5)*float2(-1,-1) + 0.5;

    float3 ret4;
    ret4 = tex2D(sampler_main, uv_echo3 ).xyz;
    ret4 += .25*GetBlur1(uv_echo3);


    ret = lerp(0.5*lerp(ret3,ret4,.5),0.5*lerp(ret,ret2,.5),.5);


    // little bit of noise:
    ret *= 1 + 0.05*(tex2D(sampler_noise_lq, rand_frame.xy 
           + uv*texsize.xy*texsize_noise_lq.zw).xxx*2-1);

    // palettize:
    ret = pow(ret, float3(0.5, 0.5, 0.7));

    ret = (ret-0.1)*2;
ret *= ret;
ret *= 7.2575654;
ret = pow(ret,1-ret);   
    //ret.xyz *= 2; // a little bit of overbright
}

