shader_body
{
uv = lerp(uv_orig,uv,0.3);

float2 d = texsize.zw * 3;
float3 dx = ( GetBlur1(uv + float2(1,0)*d) - GetBlur1(uv-float2(1,0)*d) );
float3 dy = ( GetBlur1(uv + float2(0,1)*d) - GetBlur1(uv-float2(0,1)*d) );

uv += float2(lum(dx),lum(dy))*texsize.zw*9;
ret = tex2d(sampler_fc_main, uv) - 0.01;

}

sawtooth grin roam.comp:
shader_body
{


    float2 uv_echo2 = (uv - 0.5)*1.000*float2(-1,1) + 0.5;
    float3 ret3 = tex2D(sampler_main, uv).xyz*+saturate(GetBlur2(uv)*2.8 - 0.13); 
    float3 ret4 = tex2D(sampler_main, uv_echo2).xyz*+saturate(GetBlur2(uv_echo2)*2.8 - 0.13);
    ret3 = abs(ret3-ret4);
    ret3 *= sqrt(ret3); //darken
    ret3 *= float3(.9,1.6,2.3);
    ret3 *= 3; //gamma
    ret3 = pow(ret3,1-ret3);


uv *=2 ;
float2 m = floor(frac(uv*0.5)*2);
uv = frac(uv)*(1-m) + (m)*frac(1-uv);
    uv = float2(rad,uv.y);


    float2 uv_echo = (uv.yx - 0.5)*1.000*float2(-1,-1) + 0.5;
    ret = tex2D(sampler_main, uv.yx).xyz*+saturate(GetBlur2(uv.yx)*2.8 - 0.13); 
    float3 ret2 = tex2D(sampler_main, uv_echo).xyz*+saturate(GetBlur2(uv_echo)*2.8 - 0.13);
    ret = lerp(ret,ret2,.5);
    ret *= ret; //darken
    ret *= float3(.9,1.6,2.3);
    ret *= 3; //gamma
    //ret *= 2;
    //ret = pow(ret,5);
    ret = .5*lum(ret);
    ret = max(ret3,.8*ret.zxy);
ret-=roam_sin*roam_cos.zxy;
}

